import json
import sys
import os
import time
from datetime import datetime

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    token = sys.argv[1]
    try:
        with open('tokens.json', 'r') as f:
            tokens = json.load(f)
    except Exception as e:
        log_error(e)
        sys.exit(1)

    if token not in tokens:
        write_access_denied()
        sys.exit(2)

    USERNAME = tokens[token]
    try:
        with open('activity.log', 'r') as f:
            activity_entries = json.loads(f.read())
    except Exception as e:
        log_error(e)
        sys.exit(1)

    rows = []
    for entry in activity_entries:
        if entry.get('user') == USERNAME:
            rows.append(f'<tr><td>{entry["timestamp"]}</td><td>{entry["action"]}</td></tr>')

    try:
        with open('report.html', 'w') as f:
            f.write(f'<html><body><table>{"".join(rows)}</table></body></html>')
    except Exception as e:
        log_error(e)
        sys.exit(1)

    try:
        with open('report.log', 'a') as f:
            f.write(f"{datetime.now().strftime('%Y-%m-%dT%H:%M:%S')}\t{USERNAME}\t{len(rows)}\n")
    except Exception as e:
        log_error(e)
        sys.exit(1)

    sys.exit(0)

def write_access_denied():
    try:
        with open('report.html', 'w') as f:
            f.write('<html><body>Access denied</body></html>')
    except Exception as e:
        log_error(e)
        sys.exit(1)

    try:
        with open('report.log', 'a') as f:
            f.write(f"{datetime.now().strftime('%Y-%m-%dT%H:%M:%S')}\tERROR\tAccess denied\n")
    except Exception as e:
        log_error(e)
        sys.exit(1)

def log_error(e):
    with open('report.log', 'a') as f:
        f.write(f"{datetime.now().strftime('%Y-%m-%dT%H:%M:%S')}\tERROR\t{e}\n")

if __name__ == "__main__":
    main()
